 return '<div class="card-body">'+back+'<h3>'+esc(merchant.name)+' · 全部商品</h3></div>'+businessSummary(o,rows)+table(['商品名称','所属店铺','本组织应收','已到账','操作'],products.filter(p=>shops.some(z=>z.id===p.shop&&z.org===merchant.id)).map(p=>{const t=orgTotals(o,rows.filter(x=>x.product===p.id));return tr([esc(p.name),esc(shops.find(z=>z.id===p.shop).name),money(t.due),money(t.settled),action('查看订单','association-product',p.id,'link')]);}));
