function entityContent(o){if(state.tab==='项目管理')return foundationProjects(o);if(state.tab==='商家管理')return associationBusiness(o);if(state.tab==='操作记录')return logTable(logs.filter(l=>l.org===o.id));if(['分账','分账数据'].includes(state.tab))return settlement(o);if(state.tab==='店铺')return shopPanel(o);if(state.tab==='商品与订单')return productOrders(o);if(state.tab==='公益贡献')return '<div class="card-body"><h3 class="section-title">已到账公益贡献</h3>'+kv([['累计已到账公益款',money(o.contribution||0)],['关联项目','让乡村孩子有书可读'],['接收机构','春禾公益基金会'],['统计口径','公益机构实际到账金额']])+'</div>';if(state.tab==='资质材料')return '<div class="card-body"><h3 class="section-title">资质信息</h3>'+kv([['证件类型',o.type==='高校'?'事业单位法人证书':'社会组织法人登记证书'],['资质状态','已核验 · 有效'],['核验日期','2026-10-20'],['有效期','2026-01-01 至 2030-12-31']])+'<div class="divider"></div>'+action('查看资质示意','document',o.id)+'</div>';if(state.tab==='收款资料')return '<div class="card-body"><h3 class="section-title">当前生效收款配置</h3>'+kv([['收款主体',o.name],['微信商户号','190****001'],['收款账号','已脱敏 · **** 0826'],['配置状态','已核验'],['生效版本','v1'],['审批日期','2026-10-20']])+'</div>';return '<div class="card-body"><h3 class="section-title">组织基本资料</h3>'+kv([['组织名称',o.name],['组织类型',o.type],['组织编号',o.code],['入驻状态',o.status],['组织管理员',o.admin],['联系电话',o.phone],['邀请方',o.invite||'—'],['入驻日期','2026-10-20']])+'<div class="divider"></div><h3 class="section-title">组织介绍</h3><p class="description">'+esc(o.type==='商家'?'经营公益义卖商品，以日常消费支持公益项目。':'参与公益项目合作与执行，按授权管理组织资料及相关业务。')+'</p></div>';}
function shopPanel(o){const list=shops.filter(s=>s.org===o.id);if(!list.length)return empty('当前商家暂无已开通店铺。');if(!list.some(s=>s.id===state.shop))state.shop=list[0].id;const s=list.find(x=>x.id===state.shop);let body='';if(state.shopTab==='商品管理')body=productTable(o);else if(state.shopTab==='订单管理')body=orderList(o);else if(state.shopTab==='资质信息')body='<div class="card-body">'+kv([['实际卖方',o.name],['营业资质','已核验'],['资质有效期','2026-01-01 至 2030-12-31'],['适用范围','一般商品经营']])+'</div>';else if(state.shopTab==='客服配置'){const shop=window.WorkbenchData.shops.find(x=>x.id===s.id),service=CS.resolve(null,shop).account;body='<div class="card-body">'+kv([['企业名称',CS.config().enterpriseName],['企业 ID',CS.config().corpId],['店铺默认客服',service?.name||'暂无可用客服'],['客服账号 ID（open_kfid）',service?.id||'未配置'],['客服链接',service?.url||'未配置'],['接待人员（成员 UserID）',CS.staff(service)||'未配置'],['平台兜底客服',CS.account(CS.config().fallbackId)?.name||'未配置']])+'</div>'; }else body='<div class="card-body"><h3 class="section-title">店铺资料</h3>'+kv([['店铺名称',s.name],['店铺编号',s.code],['所属商家',o.name],['经营模式',s.kind],['实际卖方',o.name],['开通状态',s.status],['客服服务时间','09:00—18:00'],['生效版本','v2']])+'</div>';return '<div class="shop-layout"><aside class="shop-list"><input type="search" aria-label="搜索店铺" placeholder="搜索店铺名称" id="shop-search">'+list.map(x=>action(esc(x.name)+'<small>'+x.code+' · '+x.status+'</small>','shop',x.id,'shop-item'+(x.id===s.id?' active':''))).join('')+'</aside><div class="shop-content"><div class="shop-title">'+icon('shop')+esc(s.name)+badge(s.status)+'</div>'+tabs(['店铺资料','资质信息','客服配置','商品管理','订单管理'],state.shopTab,'shop-tab')+body+'</div></div>';}
