function settlement(o,shopId='',scopeRows=null){const f=state.settlementFilters;const base=scopeRows||orgOrders(o).filter(x=>!shopId||x.shop===shopId);const rows=base.filter(x=>(!f.q||x.id.includes(f.q))&&(!f.status||x.split===f.status)&&(!f.pickup||(f.pickup==='是')===(x.method==='现场交付'))&&(!f.merchant||x.org===f.merchant)&&(!f.shop||x.shop===f.shop)&&(!f.product||x.product===f.product)&&(!f.start||x.date.slice(0,10)>=f.start)&&(!f.end||x.date.slice(0,10)<=f.end)&&(!f.receivedStart||x.received.slice(0,10)>=f.receivedStart)&&(!f.receivedEnd||(x.received&&x.received.slice(0,10)<=f.receivedEnd)));const share=o.type==='基金会'?.15:o.type==='商协会'?.05:o.type==='高校'?.03:1;const sum=k=>money(rows.reduce((s,r)=>s+r[k]*share,0));return '<form class="filters" data-filter="settlement"><label class="field grow">订单号<input name="q" type="search" placeholder="输入订单号" value="'+esc(f.q||'')+'"></label>'+selectField('是否现场领取','pickup',['是','否'],f.pickup)+selectField('分账状态','status',['分账成功','待分账','部分分账','分账异常'],f.status)+(o.type==='商家'?'':scopeSelect('商家','merchant',orgs.filter(x=>x.type==='商家'),f.merchant)+scopeSelect('店铺','shop',shops,f.shop)+scopeSelect('商品','product',products,f.product))+'<label class="field">下单开始日期<input type="date" name="start" value="'+esc(f.start||'')+'"></label><label class="field">下单结束日期<input type="date" name="end" value="'+esc(f.end||'')+'"></label><label class="field">到账开始日期<input type="date" name="receivedStart" value="'+esc(f.receivedStart||'')+'"></label><label class="field">到账结束日期<input type="date" name="receivedEnd" value="'+esc(f.receivedEnd||'')+'"></label><button class="btn primary" type="submit">查询</button>'+action('重置','reset-filter','settlement')+'</form>'+businessSummary(o,rows)+table(['订单号','所属商家 / 店铺','实付金额','退款金额','应分金额','已分金额','分账状态','明细'],rows.flatMap(x=>[tr([action(x.id,'order',x.id,'link'),esc(org(x.org).name)+'<div class="tiny muted">'+esc(shops.find(s=>s.id===x.shop).name)+'</div>',money(x.paid),money(x.refund),money(o.type==='基金会'?window.WorkbenchRules.fundDue(x):x.due*share),money(o.type==='基金会'?x.fundSettled:x.settled*share),badge(x.split),action(state.expanded===x.id?'收起':'展开','expand-split',x.id,'link')])].concat(state.expanded===x.id?['<tr class="subrow"><td colspan="8">'+splitDetail(x,o)+'</td></tr>']:[])))+pager(rows.length);}
