function applicationsPage(){return header('我的申请','查看本人提交的申请、审批环节及处理结果。')+'<section class="card">'+empty('当前账号暂无本人提交的申请。业务审批待办请进入审批中心。')+'</section>';}
function accountsPage(){const f=currentFilters(),rows=accounts.filter(x=>basicMatch(x,f.q)&&(!f.status||x.status===f.status));return header('账号管理','查询账号、维护系统角色授权及账号启停状态。')+'<section class="card">'+filterForm(selectField('账号状态','status',['正常','停用'],f.status),'list','搜索姓名 / 手机号 / 组织')+table(['账号姓名','手机号码','所属组织','角色','状态','操作'],rows.map(a=>tr([a.name,a.phone,a.org,a.role,badge(a.status),action('查看 / 授权','account',a.id,'link')])))+pager(rows.length)+'</section>';}
function exceptionsPage(){const refund=state.exceptionTab==='退款异常';const rows=refund?[]:orders.filter(o=>o.split==='分账异常');return header('资金异常','查看异常原因，记录处理结果并跟进渠道执行状态。')+'<section class="card">'+tabs(['退款异常','分账异常'],state.exceptionTab,'exception-tab')+table(['关联订单','所属商家','异常类型','金额','当前状态','操作'],rows.map(o=>tr([action(o.id,'order',o.id,'link'),org(o.org).name,'接收方收款配置异常',money(o.due),badge('待处理'),action('处理异常','exception',o.id,'link')])))+pager(rows.length)+'</section>';}
function bannerPage(){return header('平台运营','配置义卖首页 Banner，管理展示顺序、上线时间和跳转目标。',action(icon('plus')+'新建 Banner','banner-new','','btn primary'))+'<section class="card"><div class="card-body"><div class="banner-grid">'+banners.slice().sort((a,b)=>a.sort-b.sort).map(b=>'<div class="banner-item"><div class="banner-art"><small>SHANXING · 每一份善意都有回响</small><h3>'+esc(b.name)+'</h3><p>公益义卖 · 与你同行</p></div><div class="banner-caption"><div>'+badge(b.status)+'<p>排序 '+b.sort+' · '+esc(projects.find(p=>p.id===b.project)?.name||'项目不可用')+'</p><p>'+esc(b.start.replace('T',' '))+(b.end?' 至 '+esc(b.end.replace('T',' ')):' 起')+'</p></div>'+action('编辑','banner',b.id,'link')+'</div></div>').join('')+'</div></div></section>';}
function platformCustomerServicePage(switcher){
 const config=CS.config();
 return header('平台运营','维护首页内容及平台微信客服。')+'<section class="card">'+switcher+'<div class="card-body"><p class="notice">所有店铺统一使用平台企业 ID；各店铺创建对应客服账号，接待人员作为平台企业微信成员配置。当前为示例数据。</p>'+kv([['企业名称',config.enterpriseName],['微信客服企业 ID',config.corpId],['平台兜底客服',CS.account(config.fallbackId)?.name||'未配置'],['接待人员管理','各店铺接待人员统一加入平台企业微信，在对应微信客服账号下配置'],['自动同步',CS.syncLabel()],...(CS.syncState().error?[['同步异常',CS.syncState().error]]:[])])+'<div class="flex wrap" style="margin-top:20px">'+action('配置企业信息','platform-service')+'</div></div>'+table(['客服账号','账号 ID','接待人员','状态','用途','操作'],CS.accounts().map(a=>tr([esc(a.name),esc(a.id),esc(CS.staff(a)||'未配置'),badge(a.removed?'已失效':a.enabled?'已启用':'已停用'),a.id===config.fallbackId?'平台兜底':'商品 / 店铺可选',action('查看账号','platform-service-account',a.id,'link')+' · '+action('测试咨询','platform-service-test',a.id,'link')+' · '+(a.id!==config.fallbackId?action(a.enabled?'停用':'启用','platform-service-toggle',a.id,'link')+' · '+(CS.available(a)?action('设为兜底','platform-service-fallback',a.id,'link'):''): '<span class="tiny muted">默认兜底</span>')])) )+'</section>';
}
function platformCustomerServiceEditor(){
 const config=CS.config();
 formDialog('平台微信客服',field('企业名称','enterpriseName',config.enterpriseName,'text',true)+field('微信客服企业 ID','corpId',config.corpId,'text',true)+'<label class="full">平台兜底客服 <span class="required-tip">*</span><select name="fallbackId" required>'+CS.accounts().filter(a=>CS.available(a)).map(a=>'<option value="'+esc(a.id)+'"'+(a.id===config.fallbackId?' selected':'')+'>'+esc(a.name)+'</option>').join('')+'</select></label><p class="tiny muted full">企业 ID 应与小程序后台绑定的微信客服企业一致；接待人员在企业微信后台配置。</p>',data=>{
  if(!/^ww[a-zA-Z0-9_]+$/.test(data.corpId.trim()))return '请填写有效的企业微信企业 ID。';
  if(!CS.available(CS.account(data.fallbackId)))return '请选择可用的兜底客服账号。';
  Object.assign(config,{enterpriseName:data.enterpriseName.trim(),corpId:data.corpId.trim(),fallbackId:data.fallbackId});record('平台客服','修改企业客服配置','');closeOverlay();render();
 });
}
function platformCustomerServiceAccount(id){
 const a=CS.account(id);if(!a)return;
 dialog('微信客服账号对应关系',kv([['企业名称',CS.config().enterpriseName],['企业 ID（CorpID）',CS.config().corpId],['客服名称',a.name],['客服账号 ID（open_kfid）',a.id],['客服链接',a.url]])+'<h3 class="section-title">接待人员</h3>'+table(['成员姓名','企业微信成员 UserID'],a.servicers.map((name,i)=>tr([esc(name),esc(a.servicerIds?.[i]||'待同步')])),'')+'<p class="notice">在企业微信管理后台的“微信客服”中创建店铺客服账号并添加接待成员，后台每 5 分钟自动更新账号及接待人员，填写账号 ID 提交时即时校验。客服名称用于展示，系统使用企业 ID 与客服账号 ID 关联；同一账号可由多位成员接待。</p><a class="link" href="https://work.weixin.qq.com/" target="_blank" rel="noopener noreferrer">前往企业微信管理后台</a>',action('关闭','close'),true);
}
function platformCustomerServiceTest(id){const a=CS.account(id);dialog('测试咨询',CS.available(a)?'<p class="notice">原型咨询路由预览</p>'+kv([['企业名称',CS.config().enterpriseName],['接待客服',a.name],['账号 ID',a.id],['接待人员',CS.staff(a)],['客服链接',a.url]]):'<p>该客服账号不可用，将由平台兜底客服接待。</p>',action('关闭','close'));}
function homePage(){const switcher=tabs(['首页 Banner','平台客服'],state.platformTab,'platform-tab');if(state.platformTab==='首页 Banner')return bannerPage().replace('<section class="card">','<section class="card">'+switcher);return platformCustomerServicePage(switcher);}
function agreementPage(){return header('平台协议','维护协议版本、适用场景及确认记录。',action(icon('plus')+'新建协议','agreement-new','','btn primary'))+'<section class="card">'+tabs(['协议列表','确认记录'],state.agreementTab,'agreement-tab')+(state.agreementTab==='确认记录'?table(['确认主体','协议名称','版本','业务场景','确认时间'],[tr(['春禾公益基金会','公益机构及项目合作协议','v1','项目发布','2026-10-29 10:19'])]):table(['协议编号','协议名称','版本','适用场景','状态','操作'],agreements.map(a=>tr([a.id,a.name,a.version,a.scope,badge(a.status),action('查看','agreement',a.id+':'+a.version,'link')+' · '+action('创建新版本','agreement-edit',a.id+':'+a.version,'link')]))))+'</section>';}
function logTable(rows){return table(['操作时间','执行账号 / 身份','所属组织','操作对象','操作内容','结果'],rows.map(l=>tr([l.time,esc(l.who)+'<div class="tiny muted" style="margin-top:5px">'+esc(l.role)+'</div>',org(l.org)?.name||'平台',esc(l.object)+(l.project?'<div class="tiny muted" style="margin-top:5px">所属项目：'+esc(l.project)+'</div>':''),esc(l.action),badge(l.result)])))+pager(rows.length);}
function logsPage(){const f=currentFilters();const rows=logs.filter(l=>basicMatch({...l,orgName:org(l.org)?.name},f.q)&&(!f.org||l.org===f.org)&&(!f.project||l.project===f.project));return header('操作记录','按组织、项目及业务对象追溯操作与审批过程。')+'<section class="card">'+tabs(['操作记录','审批记录'],state.logTab,'log-tab')+filterForm('<label class="field">所属组织<select name="org"><option value="">全部组织</option>'+orgs.map(o=>'<option value="'+o.id+'"'+(f.org===o.id?' selected':'')+'>'+esc(o.name)+'</option>').join('')+'</select></label>'+selectField('所属项目','project',['让乡村孩子有书可读'],f.project),'list','搜索操作对象 / 内容 / 执行账号')+(state.logTab==='操作记录'?logTable(rows):logTable(rows.filter(l=>/审批|通过|驳回/.test(l.action)) ))+'</section>';}
function dialog(title,body,foot='',wide=false){priorFocus=document.activeElement;$('#overlay').innerHTML='<div class="overlay-shade"><section class="dialog '+(wide?'wide':'')+'" role="dialog" aria-modal="true" aria-label="'+esc(title)+'"><div class="dialog-head"><h2>'+esc(title)+'</h2>'+action(icon('close'),'close','','icon-btn')+'</div><div class="dialog-body">'+body+'</div>'+(foot?'<div class="dialog-foot">'+foot+'</div>':'')+'</section></div>';$('#overlay').querySelector('input,select,textarea,button')?.focus();}
function formDialog(title,fields,onSubmit,button='保存'){formHandler=onSubmit;dialog(title,'<form id="edit-form"><div class="form-grid">'+fields+'</div><div class="form-error" role="alert"></div><div class="dialog-foot">'+action('取消','close')+'<button class="btn primary" type="submit">'+button+'</button></div></form>');}
function field(label,name,value='',kind='text',full=false,extra=''){return '<label class="'+(full?'full':'')+'">'+label+(kind==='textarea'?'<textarea name="'+name+'" required>'+esc(value)+'</textarea>':'<input name="'+name+'" type="'+kind+'" value="'+esc(value)+'" '+extra+' required>')+'</label>';}
function closeOverlay(){state.order='';$('#overlay').innerHTML='';formHandler=null;priorFocus?.isConnected&&priorFocus.focus();}
function openReview(id){const r=reviews.find(x=>x.id===id);originReview=id;const pending=r.status==='待审批';dialog('申请详情 · '+r.id,'<div class="review-grid"><div><div class="flex wrap"><h2>'+esc(r.title)+'</h2>'+badge(r.status)+'</div><p class="description">'+esc(r.type)+' · '+r.version+' · '+org(r.org).name+'</p><div class="divider"></div>'+kv([['申请人',r.submitter],['提交时间',r.date],['所属组织',org(r.org).name],['当前环节',r.stage],['所属项目',r.project||(r.kind==='项目'?r.title:'—')],['申请版本',r.version]])+'<div class="divider"></div><h3 class="section-title">本次提交内容</h3><p class="description">'+esc(r.kind==='项目'?'更新项目介绍与执行计划，补充近期执行进展及公示材料。':r.kind==='商品'?'更新商品介绍与售价，分账计划随商品版本提交审核。':r.kind==='组织'?'提交组织基本资料、资质材料及微信收款配置。':'提交所属项目下的参与事项，包含介绍、报名要求及活动时间。')+'</p>'+(r.reason?'<p class="description">处理意见：'+esc(r.reason)+'</p>':'')+'</div><aside class="audit-panel"><h3 class="section-title">审批记录</h3><div class="timeline">'+(r.stage==='系统终审'?'<div class="timeline-item">商协会初审通过<small>向善企业商会 · 2026-10-28 16:20</small></div>':'')+'<div class="timeline-item">提交 '+r.version+'<small>'+esc(r.submitter)+' · '+r.date+'</small></div><div class="timeline-item">'+esc(r.status)+'<small>'+esc(r.stage)+'</small></div></div></aside></div>',(r.kind!=='组织'?action('客户端预览','preview',r.id):action('查看组织资料','review-org',r.org))+(pending?action('驳回','reject',id,'btn danger')+action('审批通过','approve',id,'btn primary'):action('关闭','close')),true);}
function decision(id,approved){const r=reviews.find(x=>x.id===id);formDialog(approved?'确认审批通过':'驳回申请',field(approved?'审批意见（可选）':'驳回原因','reason','','textarea',true).replace(approved?' required':'__never__',''),data=>{if(!approved&&!data.reason.trim())return '请填写驳回原因';r.status=approved?'已通过':'已驳回';r.reason=data.reason;r.stage='已处理';if(r.type==='商家入驻')org(r.org).status=approved?'已入驻':'已驳回';record(r.title,(approved?'审批通过 ':'审批驳回 ')+r.version,r.org,r.status,r.project||'');closeOverlay();render();toast('已'+(approved?'通过':'驳回')+'该申请');},approved?'确认通过':'确认驳回');}
function openOrder(id){state.order=id;const o=orders.find(x=>x.id===id);if(!o)return;let body='';if(state.orderTab==='发货与物流')body=kv([['商品',o.name+' × '+o.qty],['商品金额',money(o.paid)],['固定运费',money(o.shippingFee||0)],['实付合计',money(o.paid+(o.shippingFee||0))],['支付时间',o.date],['订单状态',o.delivery],['收货信息','林** · 138****0000 · 示例地址（已脱敏）'],['物流记录',o.delivery==='待发货'?'尚未登记发货':'顺丰速运 SF****001 · 已签收']]);if(state.orderTab==='售后退款')body=adminAfterBody(o);if(state.orderTab==='分账记录'){body=splitDetail(o);const snapshot=window.WorkbenchData.orders.find(x=>x.id===o.id);if(snapshot)body=kv([['公益模式',snapshot.donationMode==='random'?'随机随单捐':'固定份额'],['锁定公益金额',money(window.WorkbenchRules.fundDue({...snapshot,refundedQty:0}))],['原分账截止时间',window.WorkbenchRules.timeline(snapshot,Date.parse('2026-11-02T15:00')).splitAt||'等待收货']])+body;}priorFocus=document.activeElement;$('#overlay').innerHTML='<div class="overlay-shade drawer-shade"><section class="drawer '+(state.wide?'wide':'')+'" role="dialog" aria-modal="true" aria-label="订单详情"><div class="drawer-head"><div class="flex"><div class="spacer"><p class="eyebrow">ORDER DETAILS</p><h2>'+o.id+'</h2></div>'+action(icon('expand'),'widen','','icon-btn')+action(icon('close'),'close','','icon-btn')+'</div><p class="description">'+esc(org(o.org).name)+' / '+esc(shops.find(s=>s.id===o.shop).name)+'</p></div><div class="status-banner">'+icon('check')+esc(o.status)+'<span class="spacer"></span><span class="mono">实付 '+money(o.paid)+'</span></div><div class="drawer-body">'+tabs(['发货与物流','售后退款','分账记录'],state.orderTab,'order-tab')+'<div class="card-body">'+body+'</div></div><div class="drawer-foot"><span class="muted tiny">下单时间 '+o.date+'</span>'+action('查看订单对账','order-settlement',id)+'</div></section></div>';$('#overlay').querySelector('button')?.focus();}
function editAccount(id){const a=accounts.find(x=>x.id===id);dialog('账号详情',kv([['账号姓名',a.name],['手机号',a.phone],['所属组织',a.org],['当前角色',a.role],['账号状态',a.status]]),action(a.status==='正常'?'停用账号':'启用账号','account-toggle',id)+action('系统角色授权','account-role',id,'btn primary'));}
function smsFields(){return field('当前账号短信验证码','sms','','text',true,'placeholder="演示验证码 123456" autocomplete="off"');}
function editBanner(id){const b=banners.find(x=>x.id===id);formDialog(b?'编辑 Banner':'新建 Banner',field('标题','name',b?.name||'')+('<label>关联项目 <span class="required-tip">*</span><select name="project" required>'+projects.map(p=>'<option value="'+p.id+'"'+(b?.project===p.id?' selected':'')+'>'+esc(p.name)+' · '+esc(p.status)+'</option>').join('')+'</select></label><p class="full tiny muted">点击 Banner 进入项目详情；项目下线或不可用时隐藏。</p>')+field('排序','sort',b?.sort||banners.length+1,'number',false,'min="1"')+'<label>上线状态<select name="status"><option'+(b?.status==='已上线'?' selected':'')+'>已上线</option><option'+(b?.status==='待上线'?' selected':'')+'>待上线</option><option'+(b?.status==='已停用'?' selected':'')+'>已停用</option></select></label>'+field('上线时间（北京时间）','start',b?.start||'2026-10-30T09:00','datetime-local')+field('下线时间（选填）','end',b?.end||'','datetime-local').replace(' required','')+'<label class="full">Banner 图片<input type="file" name="image" accept="image/*" '+(b?'':'required')+'></label>',data=>{if(data.end&&data.end<=data.start)return '下线时间须晚于上线时间';if(!projects.some(p=>p.id===data.project&&p.status==='已发布'))return '请选择已发布项目作为跳转目标';const target=b||{id:'B'+Date.now()};Object.assign(target,{name:data.name,project:data.project,sort:Number(data.sort),status:data.status,start:data.start,end:data.end});if(!b)banners.push(target);record(target.name,b?'修改 Banner':'新建 Banner');closeOverlay();render();toast('Banner 已保存');});}
function editAgreement(id){const a=agreements.find(x=>x.id+':'+x.version===id);formDialog(a?'创建协议新版本':'新建协议',field('协议名称','name',a?.name||'')+field('适用场景','scope',a?.scope||'')+field('版本号','version',a?'v'+(parseInt(a.version.slice(1))+1):'v1')+field('生效时间','effective','2026-10-30T09:00','datetime-local')+field('协议正文','content',a?.content||'','textarea',true)+'<label class="full"><span><input style="width:auto" type="checkbox" name="reconfirm"> 需要重新确认</span></label>',data=>{if(agreements.some(g=>g.id===(a?.id)&&g.version===data.version))return '该版本号已存在，请填写新版本号';if(a)agreements.filter(g=>g.id===a.id).forEach(g=>g.status='历史版本');agreements.push({id:a?.id||'AG-'+String(agreements.length+10).padStart(2,'0'),name:data.name,scope:data.scope,version:data.version,status:'已发布',date:data.effective.replace('T',' '),content:data.content,reconfirm:data.reconfirm==='on'});record(data.name,'发布协议 '+data.version);closeOverlay();render();toast('新版本已发布，历史版本已保留');},'发布新版本');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){
 case 'nav':state.orderReturn=null;state.orderFilters={};state.route=id;state.entity='';state.tab='基本资料';state.settlementFilters={};state.expanded='';closeOverlay();render();window.scrollTo(0,0);break;
 case 'menu':$('.sidebar').classList.toggle('open');$('.mobile-veil').classList.toggle('visible');break;
 case 'account-menu':{const menu=$('.account-menu');menu.hidden=!menu.hidden;b.setAttribute('aria-expanded',String(!menu.hidden));break;}
 case 'entity':state.project='';state.projectFilters={};state.projectTab='基本信息';state.associationMerchant='';state.associationProduct='';state.shop='';state.shopTab='店铺资料';state.orderReturn=null;state.orderFilters={};state.orderListTab='订单清单';state.scroll=scrollY;state.entity=id;state.tab='基本资料';state.settlementFilters={};render();window.scrollTo(0,0);break;
 case 'back-entity':state.entity='';render();window.scrollTo(0,state.scroll);break;
 case 'tab':state.project='';state.associationMerchant='';state.associationProduct='';state.tab=id;state.expanded='';state.settlementFilters={};render();break;
 case 'platform-tab':state.platformTab=id;render();break;
 case 'platform-service':platformCustomerServiceEditor();break;
 case 'platform-service-test':platformCustomerServiceTest(id);break;
 case 'platform-service-account':platformCustomerServiceAccount(id);break;
 case 'platform-service-toggle':{const a=CS.account(id);if(!a||a.id===CS.config().fallbackId)break;a.enabled=!a.enabled;record(a.name,a.enabled?'启用客服账号':'停用客服账号','');render();break;}
 case 'platform-service-fallback':{const a=CS.account(id);if(!CS.available(a))break;CS.config().fallbackId=id;record(a.name,'设为平台兜底客服','');render();break;}
 case 'project':state.project=id;state.projectTab='基本信息';render();break;
 case 'project-back':state.project='';render();break;
 case 'project-tab':state.projectTab=id;state.expanded='';state.settlementFilters={};render();break;
 case 'project-item':state.projectItem=id;state.projectItemTab='基本信息';openProjectItem();break;
 case 'project-item-tab':state.projectItemTab=id;openProjectItem();break;
 case 'association-merchant':state.associationMerchant=id;state.associationProduct='';state.settlementFilters={};render();break;
 case 'association-product':state.associationProduct=id;state.settlementFilters={};render();break;
 case 'association-back':if(state.associationProduct)state.associationProduct='';else state.associationMerchant='';state.settlementFilters={};render();break;
 case 'shop':state.orderReturn=null;state.orderFilters={};state.orderListTab='订单清单';state.settlementFilters={};state.shop=id;state.shopTab='店铺资料';render();break;
 case 'shop-tab':state.shopTab=id;state.expanded='';state.settlementFilters={};render();break;
 case 'order-list-tab':state.orderListTab=id;state.expanded='';render();break;
 case 'return-order-source':{const origin=state.orderReturn;if(origin){Object.assign(state,origin);state.orderReturn=null;render();window.scrollTo(0,origin.scrollY);}break;}
 case 'approval-tab':state.approvalTab=id;render();break;
 case 'agreement-tab':state.agreementTab=id;render();break;
 case 'log-tab':state.logTab=id;render();break;
 case 'exception-tab':state.exceptionTab=id;render();break;
 case 'order-tab':state.orderTab=id;openOrder(state.order);break;
 case 'expand-product':case 'expand-split':state.expanded=state.expanded===id?'':id;render();break;
 case 'reset-filter':if(id==='projects')state.projectFilters={};else if(id==='settlement')state.settlementFilters={};else if(id==='orders')state.orderFilters={};else state.filters[state.route]={};render();break;
 case 'quick-order':state.orderFilters={orderStatus:id};render();break;
 case 'close':closeOverlay();break;
 case 'review':openReview(id);break;
 case 'review-org':closeOverlay();state.route={商家:'merchants',基金会:'foundations',商协会:'associations',高校:'universities'}[org(id).type];state.entity=id;state.tab='基本资料';render();break;
 case 'approve':decision(id,true);break;
 case 'reject':decision(id,false);break;
 case 'preview':{const r=reviews.find(x=>x.id===id);dialog('客户端效果预览 · '+r.version,'<div class="preview-phone"><div class="preview-top">'+esc(r.kind)+'详情</div><div class="preview-cover">让善意生长</div><div class="card-body"><h2>'+esc(r.title)+'</h2><p>'+esc(org(r.org).name)+'</p><div class="divider"></div><h3>内容介绍</h3><p>让每一份参与，为孩子带来更多阅读与陪伴。这是本次提交版本的客户端排版示意。</p>'+(r.project?'<p>所属项目：'+esc(r.project)+'</p>':'')+'</div></div>',action('返回申请详情','review',id));break;}
 case 'order':state.orderOrigin=orderContext();state.orderTab='发货与物流';state.wide=false;openOrder(id);break;
 case 'widen':state.wide=!state.wide;openOrder(state.order);break;
 case 'order-settlement':{const o=orders.find(x=>x.id===id);const origin=state.orderOrigin;closeOverlay();state.orderReturn=origin;state.route='merchants';state.entity=o.org;state.tab='店铺';state.shop=o.shop;state.shopTab='订单管理';state.orderListTab='分账对账';state.settlementFilters={...(origin?.entity===o.org?state.settlementFilters:{}),q:id};render();break;}
 case 'product':{const p=products.find(x=>x.id===id);dialog('商品详情',kv([['商品名称',p.name],['所属店铺',shops.find(s=>s.id===p.shop).name],['售价',money(p.price)],['库存',String(p.stock)],['销售状态',p.status],['审批状态',p.review]]),action('关闭','close'));break;}
 case 'org-admin':{const o=org(id);formDialog('指定 / 更换组织管理员','<label class="full">选择组织人员<select name="admin">'+[o.admin,'示例经办人'].map(n=>'<option>'+esc(n)+'</option>').join('')+'</select></label>'+smsFields(),data=>{if(data.sms!=='123456')return '短信验证码错误或已失效';o.admin=data.admin;record(o.name,'指定组织管理员：'+data.admin,id);closeOverlay();render();toast('组织管理员已更新');});break;}
 case 'account':editAccount(id);break;
 case 'account-toggle':{const ac=accounts.find(x=>x.id===id);formDialog(ac.status==='正常'?'停用账号':'启用账号',field('操作原因','reason','','textarea',true),data=>{ac.status=ac.status==='正常'?'停用':'正常';record(ac.name,'账号状态更新为'+ac.status);closeOverlay();render();toast('账号状态已更新');},'确认');break;}
 case 'account-role':{const ac=accounts.find(x=>x.id===id);formDialog('系统角色授权','<label class="full">系统角色<select name="role"><option value="">撤销系统角色</option>'+['系统商家管理员','系统基金会管理员','系统商协会管理员','系统高校管理员','系统超级管理员'].map(r=>'<option'+(ac.role===r?' selected':'')+'>'+r+'</option>').join('')+'</select></label>'+smsFields(),data=>{if(data.sms!=='123456')return '短信验证码错误或已失效';ac.role=data.role||(ac.org==='平台'?'未授予系统角色':'组织管理员');record(ac.name,'调整系统角色为'+ac.role);closeOverlay();render();toast('系统角色已更新');});break;}
 case 'exception':{const o=orders.find(x=>x.id===id);formDialog('处理分账异常','<div class="notice full">'+o.id+' · 接收方配置异常，请核实配置后记录处理结果。</div>'+field('处理说明','reason','','textarea',true),data=>{record(o.id,'记录异常处理：'+data.reason,o.org,'待渠道核实');closeOverlay();toast('已记录处理说明，渠道结果待核实');});break;}
 case 'banner':editBanner(id);break;
 case 'banner-new':editBanner('');break;
 case 'agreement':{const g=agreements.find(x=>x.id+':'+x.version===id);dialog(g.name+' · '+g.version,kv([['适用场景',g.scope],['生效时间',g.date],['当前状态',g.status],['再次确认',g.reconfirm?'需要':'按适用场景确认']])+'<div class="divider"></div><p>'+esc(g.content)+'</p>',action('关闭','close'));break;}
 case 'agreement-edit':editAgreement(id);break;
 case 'agreement-new':editAgreement('');break;
 case 'profile':dialog('账号信息',kv([['姓名','管理员'],['绑定手机号','138****0001'],['系统角色','系统超级管理员'],['授权范围','全部系统管理权限']]),action('关闭','close'));break;
 case 'password':formDialog('修改密码',field('原密码','old','','password',true)+field('新密码','next','','password',true,'minlength="8"')+field('确认新密码','confirm','','password',true,'minlength="8"'),data=>{if(data.next!==data.confirm)return '两次输入的新密码不一致';if(data.old===data.next)return '新密码须与原密码不同';closeOverlay();toast('已完成密码表单演示，未修改真实账号');},'确认修改');break;
 case 'document':dialog('资质材料示意','<div class="notice">示例材料仅用于确认查看位置和版面。</div>'+kv([['材料归属',org(id).name],['材料名称','组织登记证书'],['核验状态','已核验'],['提交版本','v1']]),action('关闭','close'));break;
 }});
document.addEventListener('submit',e=>{if(e.target.matches('[data-filter]')){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(e.target.dataset.filter==='settlement'){if((f.start&&f.end&&f.start>f.end)||(f.receivedStart&&f.receivedEnd&&f.receivedStart>f.receivedEnd)){toast('结束日期须晚于或等于开始日期');return;}state.settlementFilters=f;}else if(e.target.dataset.filter==='projects')state.projectFilters=f;else if(e.target.dataset.filter==='orders')state.orderFilters=f;else state.filters[state.route]=f;render();}if(e.target.id==='edit-form'){e.preventDefault();const result=formHandler?.(Object.fromEntries(new FormData(e.target)));if(typeof result==='string')$('.form-error').textContent=result;}});
document.addEventListener('input',e=>{if(e.target.id==='shop-search'){document.querySelectorAll('.shop-item').forEach(el=>{el.hidden=!el.textContent.includes(e.target.value)});}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#overlay').children.length)closeOverlay();else if($('.sidebar').classList.contains('open')){$('.sidebar').classList.remove('open');$('.mobile-veil').classList.remove('visible');}else if($('.account-menu'))$('.account-menu').hidden=true;}if(e.key==='Tab'&&$('#overlay').children.length){const focusable=[...$('#overlay').querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>el.offsetParent!==null);if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0]?.focus();}}});
render();

function adminProjectProgress(o,p){const data=window.WorkbenchData,shared=data.projects.find(x=>x.org===o.id&&(x.name===p.name||({'PJ001':'J001','PJ002':'J003','PJ003':'J002'}[p.id]===x.id)));if(!shared)return empty('暂无项目进展记录');const items=data.activities.filter(x=>x.project===shared.id),paid=data.donations.filter(x=>x.project===shared.id&&x.status==='支付成功'),goods=data.orders.filter(x=>x.project===shared.id),sum=goods.reduce((n,x)=>n+x.fundSettled,0)+paid.reduce((n,x)=>n+x.amount,0);return '<div class="card-body">'+kv([['筹款目标',money(shared.target)],['已筹金额',money(sum)]])+'<div class="progress"><i style="width:'+(shared.target?Math.min(100,sum/shared.target*100):0)+'%"></i></div>'+table(['来源','商品数 / 场次','购买 / 参与人数','金额'],[tr(['公益商品',new Set(goods.map(x=>x.product)).size,new Set(goods.map(x=>x.buyerId)).size,money(goods.reduce((n,x)=>n+x.fundSettled,0))]),...['项目活动','公益行动'].map(kind=>{const ids=new Set(items.filter(x=>x.kind===kind).map(x=>x.id));return tr([kind,ids.size,data.registrations.filter(x=>ids.has(x.activity)&&['已录取','资格有效'].includes(x.status)).reduce((n,x)=>n+x.people,0),money(paid.filter(x=>ids.has(x.action||x.activity)).reduce((n,x)=>n+x.amount,0))]);})])+'</div>';}

document.addEventListener('change',e=>{if(e.target.matches('form[data-filter] select[name=pickup]'))e.target.closest('form').requestSubmit();});

function adminSharedProject(p){return window.WorkbenchData.projects.find(x=>x.id===({'PJ001':'J001','PJ002':'J003'}[p.id])&&x.org===p.org);}
function adminDonationFields(p){const item=adminSharedProject(p);return item?[['心意签范围',money(item.drawMin)+' ～ '+money(item.drawMax)],['最低捐赠金额',item.minimumMode==='limited'?money(item.minimum):'不限制']]:[];}
function adminDonations(p,actionId=''){const shared=adminSharedProject(p);const data=window.WorkbenchData;const rows=shared?data.donations.filter(d=>d.project===shared.id&&(!actionId||d.action===actionId||d.activity===actionId)):[];return '<div class="card-body"><h3>个人捐赠记录</h3></div>'+table(['捐赠编号','捐赠人','来源','金额','支付状态'],rows.map(d=>tr([esc(d.id),esc(d.name),esc(data.activities.find(a=>a.id===(d.action||d.activity))?.name||'项目直接捐赠')+'<div class="tiny muted">'+(d.action?'公益行动':d.activity?'项目活动':'项目直接捐赠')+'</div>',money(d.amount),badge(d.status)])));}

function adminAfterIssue(o){const item=window.WorkbenchData.orders.find(x=>x.id===o.id);return item?.afterException||(item?.returnLogisticsUnknown?'退回物流结果待核实':item?.autoProcessFailed?'自动处理失败，待核实':'');}

function adminAfterBody(o){const item=window.WorkbenchData.orders.find(x=>x.id===o.id),R=window.WorkbenchRules;if((item?.after||o.after)==='无售后')return empty('该订单暂无售后记录。');const state=({待处理:'待商家处理',待验收:'待商家收货确认',退款处理中:'退款中',已退款:'已退款'})[item?.after]||item?.after||o.after;const quantity=item?.afterQty||1;return '<h3 class="section-title">AS'+esc(o.id.slice(2))+' · '+esc(item?.afterType||'退货退款')+'</h3>'+kv([['涉及商品',o.name+' × '+quantity],['申请金额',money(o.paid/o.qty*quantity)],['订单运费',money(o.shippingFee||0)],['当前状态',state],['申请原因','商品损坏 / 协商退款（示例）'],['退回物流',item?.returnShipments?.map(x=>x.carrier+' '+x.waybill).join('；')||'暂无退回物流'],['提交时间',item?.afterSubmittedAt||'—'],['处理截止时间',R.stamp(R.time(item?.afterSubmittedAt)+48*R.HOUR)||'—'],['寄回截止时间',R.stamp(R.time(item?.afterApprovedAt)+7*R.DAY)||'—'],['自动处理记录',item?.afterEvents?.join('；')||'—'],['自动处理异常',adminAfterIssue(o)||'—']]);}

window.addEventListener('workbench-customer-service-sync',()=>{if(state.route==='home'&&state.platformTab==='平台客服'&&!$('#overlay').children.length)render();});
